{
  "version": "1",
  "text": "This outfit blends your classic office presence with a touch of modern ease. The graphite palazzo trousers create a clean, elongating line that suits your figure perfectly, while the black blazer adds structure without feeling too rigid. Underneath, the bodysuit’s subtle embroidery introduces a gentle artistic detail that hints at your Ukrainian roots without overpowering your professional look.",
  "how_to_wear": [
    "Tuck the bodysuit in slightly at the front for a polished silhouette, letting the blazer fall naturally over it."
  ],
  "wrong_photos": [],
  "swap": {},
  "named": [],
  "about_items": [
    {
      "n": "#103·33",
      "text": "A sleek black oversize blazer with a relaxed fit and wide lapels. Its clean lines and minimal hardware give it a sophisticated edge, perfect for layering over simpler tops in an office setting."
    },
    {
      "n": "#21·26",
      "text": "A black long-sleeve bodysuit featuring delicate white embroidery of Ukrainian motifs along the sleeves and front. The subtle pattern adds cultural depth and visual interest without overwhelming your outfit."
    },
    {
      "n": "#172·12",
      "text": "High-waisted graphite palazzo trousers with a wide leg that flows from hip to hem. Their soft drape balances the structured blazer while maintaining comfort and movement throughout your workday."
    },
    {
      "n": "#144·07",
      "text": "Elegant black Givenchy slingback pumps with a pointed toe and slender heel. The glossy finish and subtle logo detail add a touch of luxury, grounding the look for both daytime meetings and evening events."
    },
    {
      "n": "#259·33",
      "text": "A single golden Cartier Juste un Clou stud earring, small yet iconic. Its warm metal tone complements your gold jewelry palette and adds a refined accent to your face."
    },
    {
      "n": "#20·39",
      "text": "A terracotta crossbody bag with a floral tapestry panel and solid brown canvas base. The earthy tones introduce warmth to your neutral palette, while its compact shape makes it practical for daily use."
    }
  ]
}
